  B  tile=sslab_11 npc=mecanico_s id=t_mecanico_n1 face=SW trainer=mecanico_n1 range=3 text=tr.mecanico_n1.pre after=tr.mecanico_n1.after beaten_flag=beaten_mecanico_n1
  C  tile=sslab_01 npc=montanista_s id=t_montanista_n2 face=SW trainer=montanista_n2 range=3 text=tr.montanista_n2.pre after=tr.montanista_n2.after beaten_flag=beaten_montanista_n2
  D  tile=sslab_00 npc=explorador_s id=t_explorador_n1 face=SW trainer=explorador_n1 range=3 text=tr.explorador_n1.pre after=tr.explorador_n1.after beaten_flag=beaten_explorador_n1
  E  tile=sslab_11 npc=mecanico_s id=t_mecanico_n2 face=SW trainer=mecanico_n2 range=3 text=tr.mecanico_n2.pre after=tr.mecanico_n2.after beaten_flag=beaten_mecanico_n2
  F  tile=sslab_01 npc=chica_s id=t_chica_n1 face=SW trainer=chica_n1 range=3 text=tr.chica_n1.pre after=tr.chica_n1.after beaten_flag=beaten_chica_n1
