@warp m -> ciudad_nodo spawn=gym_door
# Director Varo. Before the badge: the camera cuts to him, his challenge, the fight (trainer varo_g: Clubtail 45, Augeroot 42, Shellbrute 44, Quilltyrant 45, Anklord 50); a win = his speech, the Medalla Nucleo
# (flag 87, the trainer card's 8th badge), what it is, then the Ground disc and his farewell (he disbands Team Vertice: flag 942); a full bag keeps varo_disc clear and he hands the disc over (and says goodbye) the next time
# you talk to him. A loss is the blackout. Afterwards a last line.
@script varo npc
    jf badge_nucleo after
    npc_face_hero varo
    cam_npc varo
    say gym.varo.pre
    battle varo_g 0
    jv 0 1 won
    blackout
    end
  won:
    say gym.varo.win
    setf badge_nucleo
    say gym.varo.badge
    say gym.varo.about
    call varo_gift
    cam_hero
    end
  after:
    npc_face_hero varo
    cam_npc varo
    jnf varo_disc first
    jf fissure_given said
    call varo_fissure              # (contract 80): gives a disc: here the second disc (Disc 31), given at the same time as the Ground disc, or at the next talk when the bag was full
    cam_hero
    end
  first:
    call varo_gift
    cam_hero
    end
  said:
    say gym.varo.after
    cam_hero
@end
@script varo_gift called
    say gym.varo.disc
    give_item disc_tierra 1
    jv 0 0 full
    item_var 0 disc_tierra
    say gl.gift
    setf varo_disc
    say gym.varo.disc_about
    call varo_fissure
    say gym.varo.bye
    setf vertice_gone
    end
  full:
    say gl.found.full
@end
@script varo_fissure called
    jf fissure_given fdone
    say extra.varo.fissure
    give_item disc_31 1
    jv 0 0 ffull
    item_var 0 disc_31
    say gl.gift
    setf fissure_given
    say extra.varo.fissure_about
    end
  ffull:
    say gl.found.full
  fdone:
@end
